insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0001', '00000000-0000-4000-8000-000000000e01', null, 'empresa-pitch', 'pitch', 'pitch_demo', null, ARRAY[]::text[], 'Enjoy en una frase', 'Enjoy convierte cada momento de la celebración en algo que los invitados **hacen**, no que **miran**: kiss-cam, dedicatorias y retos desde su propio móvil, sin descargar nada.', 'Primeros 30 segundos de cualquier conversación (novios o sala).', 'Diferencia frente al fotomatón o el DJ: la participación es el producto.', $json$[]$json$::jsonb, 1024, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0002', '00000000-0000-4000-8000-000000000e01', null, 'empresa-icp', 'fit', 'prospeccion', null, ARRAY[]::text[], 'Cliente ideal (y cuándo no)', '- **Novios** con 100+ invitados que quieren una boda "diferente" y temen los tiempos muertos.
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0003', '00000000-0000-4000-8000-000000000e01', null, 'empresa-apertura', 'script', 'primer_contacto', null, ARRAY[]::text[], 'Apertura de la reunión', 'Hola {prospect}, gracias por el rato. Antes de enseñarte nada: ¿qué es lo que más os importa que recuerden vuestros invitados de {company}?', 'Al empezar la llamada o la visita.', 'Abre con su objetivo, no con tu producto: lo que digan es tu guion para el resto de la reunión.', $json$[]$json$::jsonb, 3072, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0004', '00000000-0000-4000-8000-000000000e01', null, 'empresa-descubrir-1', 'discovery', 'descubrimiento', null, ARRAY[]::text[], '¿Qué te preocupa que pase en el banquete?', 'Escucha si aparecen: tiempos muertos, mesas que no se mezclan, invitados mayores que no participan. Cada respuesta se conecta con un módulo.', null, null, $json$[]$json$::jsonb, 4096, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0005', '00000000-0000-4000-8000-000000000e01', null, 'empresa-descubrir-2', 'discovery', 'descubrimiento', 'no_decido_yo', ARRAY[]::text[], '¿Quién más decide?', 'Pregunta pronto si deciden ambos novios, la familia o el coordinador de la sala. Evita la objeción "lo tengo que consultar" al final.', null, null, $json$[]$json$::jsonb, 5120, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0006', '00000000-0000-4000-8000-000000000e01', null, 'empresa-obj-precio', 'objection', 'objeciones', 'precio', ARRAY[]::text[], '"Es caro"', 'No justifiques el precio. Pregunta con qué lo están comparando y vuelve a **lo que les preocupaba** del banquete (lo que dijeron en el descubrimiento). Enjoy cuesta menos por invitado que una ronda de chupitos.', 'Cuando aparece el precio antes de que hayan visto el valor.', '"Caro" casi nunca es el número: es valor no percibido todavía.', $json$[{"source":"cerebro","id":707,"title":"El cliente dice 'caro' porque traduce precio a horas trabajadas, no a valor","creator":"Alfonso y Cristian","url":"https://www.youtube.com/watch?v=ksjIkdhPxDU&t=5790"},{"source":"cerebro","id":342,"title":"El dinero nunca es el problema real","creator":"Alfonso y Cristian","url":"https://www.tiktok.com/@alfonsoychristian"}]$json$::jsonb, 6144, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0007', '00000000-0000-4000-8000-000000000e01', null, 'empresa-obj-pensar', 'objection', 'objeciones', 'tiempo', ARRAY[]::text[], '"Nos lo pensamos"', 'Pregunta qué parte quieren pensar: ¿precio, fecha o si encaja con su boda? Propón dejar la fecha **reservada 7 días sin compromiso** y agenda la llamada en ese momento.', null, null, $json$[]$json$::jsonb, 7168, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0008', '00000000-0000-4000-8000-000000000e01', null, 'empresa-cierre', 'script', 'cierre', null, ARRAY[]::text[], 'Cierre con fecha', '¿Os parece que dejemos reservada la fecha de vuestra boda y el jueves te llamo a las 18:00 para cerrar los detalles con vosotros dos?', null, 'Una sola fecha concreta: un menú de opciones hace trabajar al otro y retrasa la decisión.', $json$[]$json$::jsonb, 8192, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0009', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-pitch', 'pitch', 'pitch_demo', null, ARRAY[]::text[], 'Kiss-cam, dedicatorias y retos: el banquete se convierte en juego', 'Cada invitado participa desde su móvil (sin app) y lo que envía sale en la pantalla en directo. Nadie se queda mirando el plato.', 'Cuando han mencionado tiempos muertos o mesas que no se mezclan.', null, $json$[]$json$::jsonb, 9216, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0010', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-fit', 'fit', 'descubrimiento', null, ARRAY['bodas']::text[], 'Encaja mejor en…', 'Bodas de 100+ invitados, con pantalla o proyector en el salón. Con menos de 60 invitados, ofrece solo dedicatorias.', null, null, $json$[]$json$::jsonb, 10240, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0011', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-demo', 'tip', 'pitch_demo', null, ARRAY[]::text[], 'Enseña el móvil, no la pantalla', 'En la demo, pásale TU móvil con la kiss-cam abierta y que envíe algo: lo ve aparecer en la vista previa del dossier. Vender la experiencia > describirla.', null, null, $json$[]$json$::jsonb, 11264, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0012', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-obj-mayores', 'objection', 'objeciones', 'no_lo_necesito', ARRAY[]::text[], '"Mis invitados son mayores, no van a participar"', 'Las dedicatorias son el módulo que más usan los mayores: escribir unas palabras a los novios. Los nietos les ayudan con el móvil y eso también es parte del recuerdo.', null, null, $json$[]$json$::jsonb, 12288, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0013', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-prueba', 'proof', 'pitch_demo', null, ARRAY[]::text[], 'Participación media 92 %', 'Dato de ejemplo (sustituir por el real de Enjoy): 9 de cada 10 invitados envían al menos una kiss-cam o dedicatoria.', null, null, $json$[]$json$::jsonb, 13312, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0014', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-upsell', 'monetization', 'negociacion', null, ARRAY[]::text[], 'Pack Kiss-cam + Retos', 'Vende las experiencias en pack (no sueltas): el pack completo sube el ticket medio ~30 % y el coste marginal es casi cero. Descuento máximo autorizado: 10 %.', null, 'El margen está en el pack; las experiencias sueltas compiten con el DJ.', $json$[]$json$::jsonb, 14336, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0015', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-pitch', 'pitch', 'pitch_demo', null, ARRAY['locales']::text[], 'Un extra que vendes tú y te diferencia de la finca de al lado', 'La sala incluye Enjoy en su oferta de bodas: lo vende como propio, se queda margen y tiene un argumento que la competencia no tiene.', null, null, $json$[]$json$::jsonb, 15360, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0016', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-discovery', 'discovery', 'descubrimiento', null, ARRAY['locales']::text[], '¿Cuántas bodas hacéis al año y cuántas perdéis contra otra sala?', 'Si pierden bodas por "diferenciación", Enjoy es su argumento. Calcula con ellos: 3 bodas más al año pagan Enjoy varias veces.', null, null, $json$[]$json$::jsonb, 16384, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0017', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-obj-proveedor', 'objection', 'objeciones', 'ya_tengo_proveedor', ARRAY['locales']::text[], '"Ya trabajamos con un DJ que hace cosas parecidas"', 'Enjoy no sustituye al DJ: se apoya en él (la pantalla y el micro). Propón una boda piloto con su DJ para que lo vea funcionar juntos.', null, null, $json$[]$json$::jsonb, 17408, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0018', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-monet', 'monetization', 'negociacion', null, ARRAY['locales']::text[], 'Margen para la sala', 'Precio a la sala por evento + PVP recomendado a los novios. La sala decide si lo regala (diferenciación) o lo cobra (margen). Ejemplo: coste 250 €, PVP 450 €.', null, null, $json$[]$json$::jsonb, 18432, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0019', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e104', 'precio-presentar', 'tip', 'negociacion', 'precio', ARRAY[]::text[], 'Presenta el precio después del valor', 'La tarjeta de precio va siempre al final del dossier. Si te piden precio al principio, da una horquilla y vuelve al descubrimiento.', null, null, $json$[]$json$::jsonb, 19456, 'official', 1, null);
